#define GWENT_NO_MAIN
#include "bot_v5.cpp"
struct Hypothesis{string name;vector<int> unknown;};
vector<Hypothesis> compatible(const Game&g,int observer,const Deck&own,const vector<Deck>&library){
 int other=1-observer;map<int,int> seen;for(int s=0;s<2;s++){for(int c:g.p[s].grave)seen[c]++;for(auto u:g.p[s].board)seen[u.id]++;}for(auto w:g.weather)seen[w.second]++;for(auto [s,c]:g.openingQueue)seen[c]++;for(int c:g.p[observer].hand)seen[c]++;for(int c:g.p[observer].deck)seen[c]++;for(int c:g.p[other].known)seen[c]++;
 vector<Hypothesis> out;int need=g.p[other].hand.size()-g.p[other].known.size()+g.p[other].deck.size();
 for(auto& d:library){if(d.faction!=g.p[other].faction||d.leader!=g.p[other].leader)continue;map<int,int> counts;for(int c:d.cards)counts[c]++;for(int c:own.cards)counts[c]++;for(auto [c,n]:g.changes)counts[c]+=n;bool ok=true;for(auto [c,n]:seen){counts[c]-=n;if(counts[c]<0)ok=false;}if(!ok)continue;vector<int> pool;for(auto [c,n]:counts)for(int k=0;k<n;k++)pool.push_back(c);if((int)pool.size()==need)out.push_back({d.name,pool});}return out;
}
Game sampleBelief(const Game&g,int observer,const vector<Hypothesis>&h,Rng&r){if(h.empty())throw runtime_error("no compatible deck: expand candidate library, never inspect hidden hand");Game z=g;int o=1-observer;vector<int>pool=h[r.n(h.size())].unknown;r.shuffle(pool);int need=g.p[o].hand.size()-g.p[o].known.size();z.p[o].hand=g.p[o].known;for(int k=0;k<need;k++){z.p[o].hand.push_back(pool.back());pool.pop_back();}z.p[o].deck=pool;sort(z.p[observer].deck.begin(),z.p[observer].deck.end());r.shuffle(z.p[observer].deck);return z;}
Act beliefPolicy(const Game&g,Rng&r,int trials,const Deck&own,const vector<Deck>&library){auto h=compatible(g,g.turn,own,library);if(h.empty())throw runtime_error("no compatible hypothesis");bool identical=true;for(auto &x:h)identical&=x.unknown==h.front().unknown;Game d=sampleBelief(g,g.turn,h,r);Act solved;if(identical&&exactMove(d,solved))return solved;auto a=legal(g);if(a.size()==1)return a[0];vector<double>w(a.size(),0);for(int k=0;k<trials;k++){Game z=sampleBelief(g,g.turn,h,r);auto seed=r.next();for(int j=0;j<(int)a.size();j++){Game t=z;apply(t,a[j]);Rng rr(seed);w[j]+=rollout(t,rr,k%3)==g.turn;}}int b=0;for(int j=1;j<(int)a.size();j++)if(w[j]>w[b])b=j;return a[b];}
vector<Deck> expandLibrary(vector<Deck> lib){auto original=lib;set<string> seen;auto signature=[](const Deck&d){auto v=d.cards;sort(v.begin(),v.end());string k=to_string(d.faction)+":"+to_string(d.leader);for(int c:v)k+=","+to_string(c);return k;};for(auto&d:lib)seen.insert(signature(d));for(auto&base:original){if(base.name!="G_impera_C1"&&base.name!="G_mixed_C1"&&base.name!="G_plain_C1")continue;vector<int>units;for(int c:base.cards)if(!C[c].kind)units.push_back(c);for(int sc=1;sc<=3;sc++)for(int cl=0;cl<=2;cl++)for(int fr=0;fr<=2;fr++)for(int rain=0;rain<=1;rain++)for(int horn=0;horn<=1;horn++){if(3+sc+cl+fr+rain+horn>10)continue;Deck d=base;d.name=base.name+"_S"+to_string(sc)+"C"+to_string(cl)+"F"+to_string(fr)+"R"+to_string(rain)+"H"+to_string(horn);d.cards=units;for(auto [c,n]:vector<pair<int,int>>{{DEC,3},{SCORCH,sc},{CLEAR,cl},{id("Biting Frost"),fr},{id("Torrential Rain"),rain},{HORN,horn}})for(int j=0;j<n;j++)d.cards.push_back(c);if(seen.insert(signature(d)).second)lib.push_back(d);}}return lib;}
#ifndef BELIEF_NO_MAIN
int main(int argc,char**argv){setup();tests();auto lib=expandLibrary(loadDecks(argc>1?argv[1]:"decks.txt"));cout<<"library="<<lib.size()<<"\n";auto n=find_if(lib.begin(),lib.end(),[](auto&d){return d.name=="N_siege_F0S2C1";});auto ng=find_if(lib.begin(),lib.end(),[](auto&d){return d.name=="G_impera_C1";});int checks=0,multis=0,unchanged=0;for(int k=0;k<8;k++){Game g=start(*n,*ng,1777+k);Rng r(44+k);while(g.winner<0){if(g.turn==0){auto h=compatible(g,0,*n,lib);assert(!h.empty());bool actual=false;vector<int>pool=g.p[1].hand;pool.insert(pool.end(),g.p[1].deck.begin(),g.p[1].deck.end());for(int c:g.p[1].known)erase1(pool,c);sort(pool.begin(),pool.end());for(auto x:h)if(x.name==ng->name){actual=true;assert(x.unknown==pool);}assert(actual);checks++;multis+=h.size()>1;if(checks%17==1){Game altered=sampleBelief(g,0,h,r);auto h2=compatible(altered,0,*n,lib);assert(h2.size()==h.size());Rng a(19),b(19);assert(beliefPolicy(g,a,16,*n,lib)==beliefPolicy(altered,b,16,*n,lib));unchanged++;}if(k==0&&g.round==0&&g.steps==0){cout<<"initial compatible="<<h.size()<<"\n";}}apply(g,policy(g,r,k%3));}}cout<<"reachable positions="<<checks<<" multiple hypotheses="<<multis<<" hidden-state invariance="<<unchanged<<"\n";
 // Explicitly refuse privileged access when the library contains no legal explanation.
 Game g=start(*n,*ng,92);bool rejected=false;try{Rng r(1);beliefPolicy(g,r,16,g.turn==0?*n:*ng,{});}catch(runtime_error&){rejected=true;}assert(rejected);cout<<"empty-library rejection passed\n";
}

#endif
